namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z0-9]{6,10}$", ErrorMessage = "Student ID must be 6-10 alphanumeric characters.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "The science of numbers, quantity, and space." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Literature, writing, and language studies." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Examination of past events and civilizations." },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, DepartmentId = 1, CourseCode = "CS101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of teaching experience and specializes in programming education and software engineering.", IsFeatured = true },
            new() { Id = 2, DepartmentId = 1, CourseCode = "CS201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures including arrays, linked lists, trees, and graphs, along with algorithm design and analysis.", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park's research focuses on algorithmic complexity and optimization. He holds a PhD from MIT.", IsFeatured = true },
            new() { Id = 3, DepartmentId = 1, CourseCode = "CS310", Title = "Database Systems", Description = "Relational database design, SQL, normalization, and introduction to NoSQL systems.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Prof. Maria Garcia", InstructorBio = "Prof. Garcia worked at Oracle for a decade before joining academia. Her focus is distributed data systems." },
            new() { Id = 4, DepartmentId = 2, CourseCode = "MATH101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions with applications.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Robert Liu", InstructorBio = "Dr. Liu is an award-winning educator with publications in mathematical analysis.", IsFeatured = true },
            new() { Id = 5, DepartmentId = 2, CourseCode = "MATH202", Title = "Linear Algebra", Description = "Vector spaces, matrices, determinants, eigenvalues, and linear transformations.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", InstructorName = "Dr. Emily Watson", InstructorBio = "Dr. Watson specializes in applied linear algebra and numerical methods." },
            new() { Id = 6, DepartmentId = 2, CourseCode = "MATH301", Title = "Probability & Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. Robert Liu", InstructorBio = "Dr. Liu is an award-winning educator with publications in mathematical analysis." },
            new() { Id = 7, DepartmentId = 3, CourseCode = "ENG101", Title = "English Composition", Description = "Develop clear, effective writing skills through essays, research papers, and peer review.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", InstructorName = "Prof. Angela Morrison", InstructorBio = "Prof. Morrison is a published author and writing coach with expertise in rhetoric and composition." },
            new() { Id = 8, DepartmentId = 3, CourseCode = "ENG220", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present.", Credits = 3, Schedule = "Mon/Wed 3:30–4:50 PM", InstructorName = "Dr. David Thompson", InstructorBio = "Dr. Thompson's research covers 20th-century American fiction and cultural criticism." },
            new() { Id = 9, DepartmentId = 4, CourseCode = "PHYS101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Thu Lab 2:00–4:00 PM", InstructorName = "Dr. Alan Foster", InstructorBio = "Dr. Foster is an experimental physicist whose research focuses on optics and wave phenomena.", IsFeatured = true },
            new() { Id = 10, DepartmentId = 4, CourseCode = "PHYS202", Title = "Electromagnetism", Description = "Electric fields, magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM + Fri Lab 1:00–3:00 PM", InstructorName = "Dr. Nina Patel", InstructorBio = "Dr. Patel has published extensively on electromagnetic theory and quantum optics." },
            new() { Id = 11, DepartmentId = 5, CourseCode = "HIST101", Title = "World History to 1500", Description = "Major civilizations, cultural exchanges, and political developments from antiquity to the early modern period.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", InstructorName = "Dr. William Okafor", InstructorBio = "Dr. Okafor specializes in ancient Mediterranean and African civilizations." },
            new() { Id = 12, DepartmentId = 5, CourseCode = "HIST250", Title = "Modern European History", Description = "Europe from the Enlightenment through the 20th century, including revolutions, wars, and social change.", Credits = 3, Schedule = "Mon/Wed 10:00–11:20 AM", InstructorName = "Dr. Clara Hoffmann", InstructorBio = "Dr. Hoffmann is an expert in modern German and French history with a focus on intellectual movements." },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public string GetDepartmentName(int departmentId) =>
        _departments.FirstOrDefault(d => d.Id == departmentId)?.Name ?? "Unknown";
}

